import { useEffect, useMemo, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import Navbar from '@/components/feature/Navbar';
import Footer from '@/components/feature/Footer';
import Breadcrumb from '@/components/base/Breadcrumb';
import { movies, categories } from '@/mocks/movies';

const categoryNameMap: Record<string, string> = {
  all: '全部',
  movie: '电影',
  tv: '电视剧',
  variety: '综艺',
  anime: '动漫',
};

export default function CategoryPage() {
  const { slug } = useParams<{ slug: string }>();
  const [activeCategory, setActiveCategory] = useState(slug || 'all');

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [slug]);

  useEffect(() => {
    if (slug) {
      setActiveCategory(slug);
    }
  }, [slug]);

  const filteredMovies = useMemo(() => {
    if (activeCategory === 'all') return movies;
    return movies.filter((m) => m.category === activeCategory);
  }, [activeCategory]);

  const categoryLabel = categoryNameMap[activeCategory] || '全部';

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify({
            '@context': 'https://schema.org',
            '@type': 'WebPage',
            name: `四虎影视 - ${categoryLabel}分类`,
            description: `四虎影视${categoryLabel}分类，海量高清${categoryLabel}资源免费在线观看。`,
            url: `https://jointmove.github.io/category/${activeCategory}`,
            breadcrumb: {
              '@type': 'BreadcrumbList',
              itemListElement: [
                { '@type': 'ListItem', position: 1, name: '首页', item: 'https://jointmove.github.io' },
                { '@type': 'ListItem', position: 2, name: categoryLabel },
              ],
            },
          }),
        }}
      />

      <Navbar />
      <main className="pt-16">
        <div className="bg-background-50">
          <div className="max-w-7xl mx-auto">
            <Breadcrumb
              items={[
                { label: '首页', path: '/' },
                { label: categoryLabel },
              ]}
            />
          </div>
        </div>

        <section className="w-full px-4 md:px-6 py-10 bg-background-50">
          <div className="max-w-7xl mx-auto">
            <div className="mb-8">
              <h1 className="text-2xl md:text-3xl font-heading font-bold text-foreground-900 mb-2">
                {categoryLabel}
              </h1>
              <p className="text-sm text-foreground-500">
                共 {filteredMovies.length} 部作品
              </p>
            </div>

            <div className="flex items-center flex-wrap gap-2 mb-10">
              {categories.map((cat) => (
                <Link
                  key={cat.slug}
                  to={`/category/${cat.slug}`}
                  onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
                  className={`px-5 py-2.5 rounded-full text-sm font-medium transition-all duration-300 whitespace-nowrap cursor-pointer ${
                    activeCategory === cat.slug
                      ? 'bg-primary-500 text-background-50'
                      : 'bg-background-100 text-foreground-600 hover:bg-background-200'
                  }`}
                >
                  <span className="w-4 h-4 flex items-center justify-center inline-block mr-1.5">
                    <i className={`${cat.icon} text-sm`}></i>
                  </span>
                  {cat.name}
                </Link>
              ))}
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4 md:gap-5">
              {filteredMovies.map((movie) => (
                <Link
                  key={movie.id}
                  to={`/article/${movie.slug}`}
                  className="group cursor-pointer"
                  onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
                >
                  <div className="relative rounded-xl overflow-hidden aspect-[3/4] mb-3">
                    <img
                      src={movie.poster}
                      alt={movie.title}
                      className="w-full h-full object-cover object-top group-hover:scale-105 transition-transform duration-500"
                    />
                    <div className="absolute top-2 left-2 flex flex-wrap gap-1">
                      {movie.tags.map((tag) => (
                        <span
                          key={tag}
                          className="px-2 py-0.5 bg-primary-500/90 text-background-50 text-xs rounded-md font-medium"
                        >
                          {tag}
                        </span>
                      ))}
                    </div>
                    <div className="absolute top-2 right-2">
                      <span className="px-2 py-0.5 bg-background-950/70 text-accent-400 text-xs rounded-md font-bold">
                        {movie.rating}
                      </span>
                    </div>
                  </div>
                  <h3 className="text-sm font-medium text-foreground-900 group-hover:text-primary-600 transition-colors duration-200 line-clamp-1">
                    {movie.title}
                  </h3>
                  <div className="flex items-center gap-2 mt-1 text-xs text-foreground-500">
                    <span>{movie.type}</span>
                    <span>·</span>
                    <span>{movie.year}</span>
                  </div>
                </Link>
              ))}
            </div>

            {filteredMovies.length === 0 && (
              <div className="text-center py-20">
                <div className="w-16 h-16 flex items-center justify-center mx-auto mb-4">
                  <i className="ri-film-line text-4xl text-foreground-300"></i>
                </div>
                <p className="text-foreground-500">暂无相关内容</p>
              </div>
            )}
          </div>
        </section>
      </main>
      <Footer />
    </>
  );
}